// ── Noto Animated Emoji CDN ──────────────────────────────────────
// https://fonts.gstatic.com/s/e/notoemoji/latest/{hex}/512.gif
function notoUrl(emoji) {
  // Convierte emoji a hex unicode para el CDN de Google Fonts
  const cp = emoji.codePointAt(0).toString(16);
  return `https://fonts.gstatic.com/s/e/notoemoji/latest/${cp}/512.gif`;
}

