function showEmojiPicker(onSelect) {
  const existing = document.getElementById('emoji-picker-sheet');
  if (existing) { existing.remove(); return; }
  let mode = 'fluent', currentCat = 0, swipeStartX = 0, swipeStartY = 0;
  const sheet = document.createElement('div');
  sheet.id = 'emoji-picker-sheet';
  sheet.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:9999999;background:#fff;border-radius:24px 24px 0 0;padding:0 0 32px;box-shadow:0 -8px 40px rgba(0,0,0,0.18);animation:slideUp 0.28s cubic-bezier(.34,1.3,.64,1);max-height:72vh;display:flex;flex-direction:column;';
  // Ocultar subcategorías para que no queden por encima del picker
  const _subcatsEl = document.getElementById('wp-scats');
  if (_subcatsEl) { _subcatsEl.style.zIndex = '-1'; _subcatsEl.style.pointerEvents = 'none'; }
  const _restoreSubcats = () => {
    const el = document.getElementById('wp-scats');
    if (el) { el.style.zIndex = ''; el.style.pointerEvents = ''; }
  };
  sheet.innerHTML = `
    <div style="width:36px;height:4px;background:#e5e7eb;border-radius:4px;margin:12px auto 0;flex-shrink:0;"></div>
    <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px 0;flex-shrink:0;">
      <div style="font-size:16px;font-weight:800;color:#111;">Elige tu ícono</div>
      <button id="emoji-picker-close" style="width:30px;height:30px;border-radius:50%;border:none;background:#f3f4f6;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;">✕</button>
    </div>
    <div style="display:flex;gap:8px;padding:10px 16px 0;flex-shrink:0;">
      <button id="mode-fluent" style="flex:1;padding:7px;border-radius:12px;border:none;background:#111;color:white;font-size:12px;font-weight:700;cursor:pointer;">✨ Fluent 3D</button>
      <button id="mode-animated" style="flex:1;padding:7px;border-radius:12px;border:none;background:#f3f4f6;color:#6b7280;font-size:12px;font-weight:700;cursor:pointer;">🎞️ Animados</button>
    </div>
    <div id="emoji-tabs" style="display:flex;overflow-x:auto;padding:8px 16px 0;gap:4px;flex-shrink:0;scrollbar-width:none;"></div>
    <div id="emoji-grid" style="flex:1;overflow-y:auto;padding:14px 16px;display:grid;grid-template-columns:repeat(5,1fr);gap:10px;scrollbar-width:none;"></div>
  `;
  document.body.appendChild(sheet);
  function renderTabs() {
    const tabs = document.getElementById('emoji-tabs');
    const secs = mode === 'fluent' ? FLUENT_SECTIONS : PIN_CATEGORIES;
    tabs.innerHTML = secs.map((c,i) => `<button class="emoji-tab" data-cat="${i}" style="flex-shrink:0;padding:7px 12px;border:none;background:none;font-size:12px;font-weight:600;color:${i===0?'#6366f1':'#9ca3af'};border-bottom:2px solid ${i===0?'#6366f1':'transparent'};cursor:pointer;white-space:nowrap;">${c.label}</button>`).join('');
    tabs.querySelectorAll('.emoji-tab').forEach(t => t.addEventListener('click', () => activateCat(parseInt(t.dataset.cat))));
  }
  function renderGrid(idx, dir=0) {
    const grid = document.getElementById('emoji-grid');
    if (dir) { grid.style.transition='none'; grid.style.opacity='0'; grid.style.transform=`translateX(${dir>0?'30px':'-30px'})`; }
    const items = mode === 'fluent'
      ? (FLUENT_SECTIONS[idx]?.items||[]).map(i=>({emoji:i.emoji,url:i.url}))
      : (PIN_CATEGORIES[idx]?.emojis||[]).map(e=>({emoji:e,url:notoUrl(e)}));
    grid.innerHTML = items.map(i=>`
      <button class="emoji-pick-btn" data-emoji="${i.emoji}" data-url="${i.url}" style="aspect-ratio:1;border:2px solid #f3f4f6;background:#fafafa;border-radius:16px;cursor:pointer;padding:8px;display:flex;align-items:center;justify-content:center;overflow:hidden;-webkit-tap-highlight-color:transparent;">
        <img src="${i.url}" style="width:100%;height:100%;object-fit:contain;" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
        <span style="display:none;font-size:26px;width:100%;height:100%;align-items:center;justify-content:center;">${i.emoji}</span>
      </button>`).join('');
    if (dir) requestAnimationFrame(()=>{ grid.style.transition='opacity .18s,transform .18s'; grid.style.opacity='1'; grid.style.transform='translateX(0)'; });
    grid.querySelectorAll('.emoji-pick-btn').forEach(btn=>btn.addEventListener('click',()=>{
      btn.style.borderColor='#6366f1'; btn.style.background='#eef2ff';
      setTimeout(()=>{ onSelect(btn.dataset.emoji, btn.dataset.url); _restoreSubcats(); sheet.remove(); },100);
    }));
  }
  function activateCat(idx, dir=0) {
    currentCat=idx;
    document.querySelectorAll('#emoji-picker-sheet .emoji-tab').forEach(t=>{
      const a=parseInt(t.dataset.cat)===idx;
      t.style.color=a?'#6366f1':'#9ca3af'; t.style.borderBottomColor=a?'#6366f1':'transparent';
    });
    document.querySelector(`#emoji-picker-sheet .emoji-tab[data-cat="${idx}"]`)?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});
    renderGrid(idx,dir);
  }
  function switchMode(m) {
    mode=m; currentCat=0;
    document.getElementById('mode-fluent').style.cssText=`flex:1;padding:7px;border-radius:12px;border:none;font-size:12px;font-weight:700;cursor:pointer;background:${m==='fluent'?'#1a5cf5':'#f3f4f6'};color:${m==='fluent'?'white':'#6b7280'};`;
    document.getElementById('mode-animated').style.cssText=`flex:1;padding:7px;border-radius:12px;border:none;font-size:12px;font-weight:700;cursor:pointer;background:${m==='animated'?'#1a5cf5':'#f3f4f6'};color:${m==='animated'?'white':'#6b7280'};`;
    renderTabs(); renderGrid(0);
  }
  document.getElementById('mode-fluent').addEventListener('click',()=>switchMode('fluent'));
  document.getElementById('mode-animated').addEventListener('click',()=>switchMode('animated'));
  document.getElementById('emoji-picker-close').addEventListener('click',()=>{ _restoreSubcats(); sheet.remove(); });
  const grid=document.getElementById('emoji-grid');
  grid.addEventListener('touchstart',e=>{swipeStartX=e.touches[0].clientX;swipeStartY=e.touches[0].clientY;},{passive:true});
  grid.addEventListener('touchend',e=>{
    const dx=e.changedTouches[0].clientX-swipeStartX,dy=e.changedTouches[0].clientY-swipeStartY;
    if(Math.abs(dx)<40||Math.abs(dy)>Math.abs(dx))return;
    const secs=mode==='fluent'?FLUENT_SECTIONS:PIN_CATEGORIES;
    if(dx<0&&currentCat<secs.length-1)activateCat(currentCat+1,-1);
    if(dx>0&&currentCat>0)activateCat(currentCat-1,1);
  },{passive:true});
  renderTabs(); renderGrid(0);
}


